/* From Uiverse.io by laminelawal - Tags: card, iphone, widget */
.__UIV_SCOPE__ .phoneContainer {
  width: 185px;
  height: 350px;
  background-color: black;
  border-radius: 20px;
  position: relative;
}

.__UIV_SCOPE__ .screen {
  width: 180px;
  height: 340px;
  background: rgb(255,196,196);
  background: linear-gradient(167deg, rgba(255,196,196,1) 10%, rgba(45,138,253,1) 20%, rgba(34,193,195,1) 48%, rgba(211,216,255,1) 69%, rgba(0,164,24,1) 88%);
  border-radius: 20px;
  position: absolute;
  top: 4px;
  bottom: 2px;
  right: 2px;
  left: 2px;
  box-sizing: border-box;
}

.__UIV_SCOPE__ .camera {
  width: 80px;
  background-color: black;
  position: absolute;
  height: 20px;
  top: 4%;
  right: 50%;
  transform: translate(50%, -50%);
  border-radius: 25px;
  transition: 0.3s;
  animation-name: callTransition;
  animation-duration: 1.9s;
  animation-direction: alternate;
  animation-iteration-count: infinite;
  animation-timing-function: ease;
}

@keyframes callTransition {
  15% {
    width: 40px;
  }

  95% {
    width: 95px;
    background-color: darkblue;
  }
}

.__UIV_SCOPE__ .camera:before {
  content: "";
  width: 15px;
  height: 15px;
  background-color: rgb(19, 19, 51);
  position: absolute;
  border-radius: 50%;
  left: 5px;
  top: 2px;
}

.__UIV_SCOPE__ .camera:after {
  content: "";
  width: 5px;
  height: 5px;
  background-color: lightgreen;
  position: absolute;
  border-radius: 50%;
  right: 5px;
  top: 6px;
}

.__UIV_SCOPE__ .appsContainer {
  margin-top: 10px;
  position: absolute;
  right: 50%;
  top: 40%;
  transform: translate(50%, -50%);
}

.__UIV_SCOPE__ .widgets {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
  box-sizing: border-box;
}

.__UIV_SCOPE__ .one, .__UIV_SCOPE__ .two {
  height: 80px;
  width: 80px;
  background-color: blue;
  border-radius: 10px;
  cursor: pointer;
}

.__UIV_SCOPE__ .two {
  background-color: lightblue;
}

.__UIV_SCOPE__ .oneApp, .__UIV_SCOPE__ .twoApp {
  width: 35px;
  height: 35px;
  background-color: white;
  border-radius: 5px;
  margin-top: 10px;
}

.__UIV_SCOPE__ .apps {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  margin-top: 15px;
  margin-left: 5px;
}

.__UIV_SCOPE__ .menuBar {
  display: flex;
  border-radius: 20px;
  position: absolute;
  bottom: -70px;
}

.__UIV_SCOPE__ .menuBar .twoApp:not(:last-child) {
  margin-right: 10px;
}

.__UIV_SCOPE__ .menuBar::before {
  content: "";
  position: absolute;
  width: 50px;
  height: 13px;
  background-color: lightgray;
  border: none;
  border-radius: 20px;
  top: -5px;
  right: 50%;
  transform: translate(50%, -50%);
}

.__UIV_SCOPE__ .menuBar::before {
  content: "°°°°°°";
  position: absolute;
  display: flex;
  justify-content: center;
  font-size: 18px;
  font-weight: bolder;
  color: gray;
}
